import type {Instrument,Quote} from '../../../src/markets/policy';
export const marketId='11111111-1111-4111-8111-111111111111',marketNow=Date.parse('2026-10-23T00:00:00Z');
export const marketContext={actorId:marketId,tenantId:marketId,workspaceId:marketId,accountId:marketId,mode:'paper' as const,environment:'dev' as const,capabilities:['market.read','market.watchlist.write','alerts.read'],mfaState:'verified' as const,expiresAt:new Date(marketNow+600000).toISOString()};
export const marketInstrument=(venue:'binance'|'coinbase'='binance',symbol='BTC/USDT'):Instrument=>({instrumentId:`${venue}:spot:${symbol}`,canonicalSymbol:symbol,venue,productType:'spot',intervals:['1m','1h'],timezones:['UTC'],priceKind:'top_of_book',topOfBook:true,lotSize:'0.0001',minNotional:'10'});
export const marketQuote=(i=marketInstrument()):Quote=>({instrumentId:i.instrumentId,canonicalSymbol:i.canonicalSymbol,productType:i.productType,bid:'103.900000000000000001',ask:'104.10',mid:'104',lastPrice:'104',priceKind:'top_of_book',executable:false,feeEstimate:null,slippageEstimate:null,estimates:true,lotSize:i.lotSize,minNotional:i.minNotional,provenance:{source:`approved.${i.venue}.spot`,venue:i.venue,asOf:new Date(marketNow).toISOString(),quality:'passed',license:'fixture-only',approvalRef:'fixture:r01',approvalVersion:'v2',dataSnapshotId:marketId,latencyMs:0},sequence:6});
export const marketFrame=(patch:Record<string,unknown>={})=>({streamId:marketId,sequence:6,eventId:crypto.randomUUID(),occurredAt:new Date(marketNow).toISOString(),correlationId:marketId,payloadVersion:'v1',payload:{...marketQuote()},...patch});
